function About(){return <div className="mx-auto max-w-[1160px] px-5 py-14 sm:px-8"><p className="eyebrow">ABOUT SMARTAGRI MAP</p><h1 className="serif mt-4 max-w-[760px] text-5xl leading-[1.05] sm:text-6xl">A small signal from a field can start a better season.</h1><p className="mt-6 max-w-[690px] text-lg leading-8 text-muted-foreground">SmartAgri Map is a location-first agriculture support platform connecting farmers with local field teams across Andhra Pradesh and nearby regions.</p><div className="mt-12 grid gap-5 lg:grid-cols-[1.05fr_.95fr]"><div className="rounded-3xl bg-primary p-8 text-[#f6f4e8] sm:p-10"><Sprout size={30} className="text-[#d2e4a7]"/><h2 className="serif mt-7 text-3xl">Why a map matters</h2><p className="mt-4 leading-7 text-[#d5e1d1]">A crop concern is never just a category. It happens in a particular field, under particular conditions, for a particular family. Precise location helps local officers see patterns, prioritize visits and offer guidance that fits.</p></div><div className="grid gap-4">{[{icon:Wheat,title:"Built around growers",text:"Simple reporting designed for the moments farmers need help."},{icon:ShieldCheck,title:"Clear at every step",text:"A shared status keeps the farmer and field team on the same page."},{icon:Globe2,title:"Rooted in local context",text:"A community map designed for the districts and growing seasons around us."}].map(i=><div key={i.title} className="flex gap-4 rounded-2xl border border-border bg-card p-5"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-[#e6eddd] text-primary"><i.icon size={20}/></span><div><h3 className="font-bold">{i.title}</h3><p className="mt-1 text-sm leading-6 text-muted-foreground">{i.text}</p></div></div>)}</div></div><section className="mt-8 rounded-3xl border border-border bg-card p-7 sm:p-9"><p className="eyebrow">THREE ROLES, ONE SHARED FIELD PICTURE</p><div className="mt-5 grid gap-4 md:grid-cols-3">{[{title:"Farmer",text:"Reports a field issue, shares its location, and tracks progress and officer guidance on their own reports."},{title:"Agriculture Officer",text:"Reviews community reports, updates status from Reported to In Progress to Resolved, and adds practical remarks."},{title:"Admin",text:"Keeps the network accountable with live analytics, demo-user access controls, and invalid-report management."}].map(x=><article key={x.title} className="rounded-2xl bg-[#f2f3ea] p-5"><h2 className="serif text-2xl">{x.title}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">{x.text}</p></article>)}</div></section><div className="mt-12 rounded-3xl border border-border bg-card p-7 sm:p-9"><h2 className="serif text-3xl">What we stand for</h2><div className="mt-7 grid gap-6 sm:grid-cols-3">{[["Practical","Useful steps, not noise."],["Respectful","Farmers’ time and knowledge come first."],["Accountable","Every concern has a visible path forward."]].map(([a,b])=><div key={a}><span className="text-xs font-bold uppercase tracking-widest text-[#a76e3e]">{a}</span><p className="mt-2 text-sm text-muted-foreground">{b}</p></div>)}</div></div></div>}

function compressImage(file:File):Promise<string>{return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error("Could not read that image."));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error("That image could not be opened."));img.onload=()=>{const canvas=document.createElement("canvas");const ctx=canvas.getContext("2d");if(!ctx){reject(new Error("Image preview is unavailable."));return}let scale=Math.min(1,1100/Math.max(img.width,img.height));let quality=.65;let output="";for(let pass=0;pass<6;pass++){canvas.width=Math.max(1,Math.round(img.width*scale));canvas.height=Math.max(1,Math.round(img.height*scale));ctx.drawImage(img,0,0,canvas.width,canvas.height);output=canvas.toDataURL("image/jpeg",quality);if(output.length<620000)break;if(quality>.42)quality-=.1;else scale*=.78}resolve(output)};img.src=String(reader.result)};reader.readAsDataURL(file)})}
function ReportForm(){
 const {user,reports,setReports,toast}=useApp();const [,setPath]=useLocation();
 const [name,setName]=useState(user?.name||"");const [email,setEmail]=useState(user?.email||"");const [type,setType]=useState<ProblemType|"">("");const [desc,setDesc]=useState("");const [loc,setLoc]=useState("");const [lat,setLat]=useState("");const [lng,setLng]=useState("");const [date,setDate]=useState(new Date().toISOString().slice(0,10));const [image,setImage]=useState("");const [error,setError]=useState("");const [gpsBusy,setGpsBusy]=useState(false);const [saving,setSaving]=useState(false);
 async function onImage(file?:File){if(!file)return;setError("");if(!["image/jpeg","image/png","image/webp"].includes(file.type)){setError("Choose a JPG, PNG or WEBP image.");return}if(file.size>5*1024*1024){setError("That image is over 5 MB. Please choose a smaller original.");return}try{setImage(await compressImage(file))}catch{setError("We couldn't prepare that image. Try another file.")}}
 function gps(){if(!navigator.geolocation){setError("Location services are not available in this browser.");return}setGpsBusy(true);setError("");navigator.geolocation.getCurrentPosition(pos=>{setLat(pos.coords.latitude.toFixed(6));setLng(pos.coords.longitude.toFixed(6));setGpsBusy(false)},err=>{setGpsBusy(false);setError(err.code===1?"Location permission was denied. Allow location access in your browser, or enter coordinates manually.":"We couldn't get your location. Please try again or enter coordinates manually.")},{enableHighAccuracy:true,timeout:12000})}
 function submit(e:React.FormEvent){e.preventDefault();setError("");const latitude=Number(lat),longitude=Number(lng);if(name.trim().length<2){setError("Please enter your name (at least 2 characters).");return}if(!categories.includes(type as ProblemType)){setError("Choose the issue category that fits best.");return}if(!loc.trim()){setError("Add a village, mandal or district for the field location.");return}if(desc.trim().length<10||desc.trim().length>1000){setError("Please describe the issue in 10–1,000 characters.");return}if(!date||Number.isNaN(Date.parse(date))){setError("Choose a valid date for when the issue was noticed.");return}if(!lat.trim()||!lng.trim()||!Number.isFinite(latitude)||latitude < -90||latitude>90||!Number.isFinite(longitude)||longitude < -180||longitude>180){setError("Enter valid latitude and longitude coordinates for the field, or use GPS.");return}setSaving(true);const id=`SA-${Date.now().toString().slice(-6)}`;const item:Report={id,farmerName:name.trim(),farmerEmail:user?.role==="Farmer"?user.email:(email.trim()||"guest@local"),problemType:type as ProblemType,description:desc.trim(),locationName:loc.trim(),latitude,longitude,image,date,status:"Reported",remarks:"",createdAt:new Date().toISOString()};setReports([item,...reports]);toast(`Report ${id} has been submitted.`);setSaving(false);setName(user?.name||"");setEmail(user?.email||"");setType("");setDesc("");setLoc("");setLat("");setLng("");setDate(new Date().toISOString().slice(0,10));setImage("");setPath(`/reports/${id}`)}
 return <div className="mx-auto max-w-[1050px] px-5 py-10 sm:px-8"><div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow">MAKE A FIELD REPORT</p><h1 className="serif mt-2 text-4xl sm:text-5xl">Tell us what’s happening.</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">A few details help the local team understand the issue and get to the right place.</p></div><span className="inline-flex w-fit items-center gap-2 rounded-full bg-[#e7eddc] px-4 py-2 text-xs font-bold text-primary"><ShieldCheck size={15}/> Private farmer details</span></div>
 <form onSubmit={submit} className="grid gap-6 lg:grid-cols-[1fr_320px]"><div className="space-y-5">
   <Panel title="About the issue" sub="Fields marked with * are required"><div className="grid gap-4 p-5 sm:grid-cols-2 sm:p-6"><Field label="Farmer name *"><input data-testid="input-farmer-name" value={name} onChange={e=>setName(e.target.value)} placeholder="Name of the farmer" className="input"/></Field><Field label="Email (for ownership)"><input data-testid="input-farmer-email" type="email" value={email} onChange={e=>setEmail(e.target.value)} disabled={user?.role==="Farmer"} placeholder="you@example.com" className="input disabled:cursor-not-allowed disabled:opacity-70"/></Field><Field label="Issue category *"><select data-testid="select-problem-type" value={type} onChange={e=>setType(e.target.value as ProblemType)} className="input"><option value="">Choose a category</option>{categories.map(c=><option key={c}>{c}</option>)}</select></Field><Field label="Date noticed *"><input data-testid="input-report-date" type="date" value={date} onChange={e=>setDate(e.target.value)} className="input"/></Field><div className="sm:col-span-2"><Field label="Describe the issue *"><textarea data-testid="input-description" value={desc} onChange={e=>setDesc(e.target.value)} maxLength={1000} rows={5} placeholder="What are you seeing in the field? When did it begin? What has changed?" className="input resize-y"/><div className="mt-1 text-right text-[11px] text-muted-foreground">{desc.length}/1,000 characters</div></Field></div></div></Panel>
   <Panel title="Where is the field?" sub="A precise pin helps the right local team respond."><div className="grid gap-4 p-5 sm:grid-cols-2 sm:p-6"><div className="sm:col-span-2"><Field label="Village, mandal or district *"><input data-testid="input-location-name" value={loc} onChange={e=>setLoc(e.target.value)} placeholder="e.g. Rajampet, Kadapa" className="input"/></Field></div><Field label="Latitude"><input data-testid="input-latitude" type="number" step="any" value={lat} onChange={e=>setLat(e.target.value)} placeholder="14.195000" className="input"/></Field><Field label="Longitude"><input data-testid="input-longitude" type="number" step="any" value={lng} onChange={e=>setLng(e.target.value)} placeholder="79.159000" className="input"/></Field><div className="sm:col-span-2"><Button kind="outline" onClick={gps} disabled={gpsBusy} data-testid="button-use-gps"><LocateFixed size={16}/>{gpsBusy?"Finding your location…":"Use my current location"}</Button>{lat&&lng&&<><p className="mt-3 flex items-start gap-2 text-xs text-[#45694d]" data-testid="text-coordinate-confirmation"><CheckCircle2 size={15}/> Location captured: {lat}, {lng}. Please confirm this is near the affected field.</p><div className="mt-3" data-testid="map-report-location-preview"><MapView reports={[]} height="220px" center={[Number(lat)||0,Number(lng)||0]} zoom={14}/><p className="mt-2 text-[11px] text-muted-foreground">Preview of the exact coordinates above. Drag the map to check nearby roads and landmarks.</p></div></>}</div></div></Panel>
 </div><aside className="space-y-5"><Panel title="Add a field photo" sub="An image can help identify the issue."><div className="p-5"><label className="flex min-h-[180px] cursor-pointer flex-col items-center justify-center overflow-hidden rounded-2xl border-2 border-dashed border-[#c8d4be] bg-[#f4f5eb] p-5 text-center transition-colors hover:border-primary" data-testid="label-upload-image">{image?<><img src={image} alt="Field issue preview" className="max-h-48 rounded-xl object-contain"/><span className="mt-3 text-xs font-semibold text-primary">Choose a different image</span></>:<><span className="grid h-12 w-12 place-items-center rounded-2xl bg-white text-primary shadow-sm"><Upload size={20}/></span><b className="mt-4 text-sm">Upload a field photo</b><span className="mt-1 text-xs text-muted-foreground">JPG, PNG or WEBP · up to 5 MB</span></>}<input data-testid="input-image-upload" type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" onChange={e=>void onImage(e.target.files?.[0])}/></label>{image&&<button type="button" onClick={()=>setImage("")} data-testid="button-remove-image" className="mt-2 text-xs font-semibold text-destructive">Remove photo</button>}<div className="mt-5 rounded-xl bg-[#e9eee0] p-4 text-xs leading-5 text-[#536650]"><ShieldCheck size={16} className="mb-1 text-primary"/> Your photo is stored privately in this browser prototype and attached only to this report.</div></div></Panel>
 <div className="rounded-2xl border border-border bg-card p-5"><div className="flex items-start gap-3"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[#f7e9da] text-[#a46937]"><CircleHelp size={18}/></span><div><h3 className="text-sm font-bold">Need a hand?</h3><p className="mt-1 text-xs leading-5 text-muted-foreground">Describe what you see in your own words. Your local agriculture team will review the report.</p></div></div></div>
 </aside><div className="lg:col-span-2">{error&&<div role="alert" data-testid="status-form-error" className="mb-4 rounded-xl border border-[#e9c9bd] bg-[#fbede7] px-4 py-3 text-sm font-medium text-[#984d36]">{error}</div>}<div className="flex flex-col-reverse gap-3 sm:flex-row sm:justify-end"><Button kind="outline" onClick={()=>{setName(user?.name||"");setEmail(user?.email||"");setType("");setDesc("");setLoc("");setLat("");setLng("");setImage("");setError("")}} data-testid="button-reset-form">Clear form</Button><Button type="submit" disabled={saving} data-testid="button-submit-report"><Plus size={17}/>{saving?"Submitting…":"Submit field report"}</Button></div></div></form>
 </div>
}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="block text-xs font-bold text-[#526156]">{label}<div className="mt-2">{children}</div></label>}
function ReportRoute(){const {user}=useApp();const [,setPath]=useLocation();useEffect(()=>{if(!user)setPath("/login?return=%2Freport")},[user,setPath]);if(user?.role==="Farmer")return <ReportForm/>;if(!user)return <Login redirect="/report"/>;return <div className="mx-auto max-w-3xl px-5 py-24 text-center"><span className="mx-auto grid h-14 w-14 place-items-center rounded-2xl bg-[#e5eddd] text-primary"><ShieldCheck size={25}/></span><h1 className="serif mt-5 text-4xl">Reports are created by farmers.</h1><p className="mx-auto mt-3 max-w-xl text-sm leading-6 text-muted-foreground">Your {user.role.toLowerCase()} access is for reviewing and supporting community reports. Switch to a Farmer demo account to submit an issue.</p><Link href="/dashboard" data-testid="link-report-role-dashboard" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-bold text-primary-foreground">Go to your dashboard <ArrowRight size={16}/></Link></div>}

function MapCenter({center}:{center:[number,number]}){const map=useMap();useEffect(()=>{map.setView(center,map.getZoom(),{animate:true})},[center,map]);return null}
function makeIcon(color:string){return L.divIcon({className:"map-pin",html:`<div style="height:34px;width:34px;border:3px solid #fff;border-radius:50% 50% 50% 2px;transform:rotate(-45deg);background:${color};box-shadow:0 3px 9px #234a3670;display:grid;place-items:center"><span style="color:#fff;font-size:12px;transform:rotate(45deg);font-weight:bold">•</span></div>`,iconSize:[34,34],iconAnchor:[17,32],popupAnchor:[0,-29]})}
function MapView({reports,height="600px",center=[15.05,78.7],zoom=7}:{reports:Report[];height?:string;center?:[number,number];zoom?:number}){
 return <div className="overflow-hidden rounded-2xl border border-border" style={{height}}><MapContainer center={center} zoom={zoom} scrollWheelZoom className="h-full w-full"><TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>' url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"/><MapCenter center={center}/>{reports.map(r=><Marker key={r.id} position={[r.latitude,r.longitude]} icon={makeIcon(categoryColor[r.problemType])}><Popup><div className="min-w-[185px]"><div className="mb-1 flex items-center gap-2"><span className="font-bold">{r.problemType}</span><Status status={r.status}/></div><b className="text-xs">{r.locationName}</b><p className="my-2 line-clamp-3 text-xs">{r.description}</p><div className="mb-2 text-[10px] text-gray-500">{new Date(r.date+"T00:00:00").toLocaleDateString("en-IN")} · {r.id}</div><Link href={`/reports/${r.id}`} className="text-xs font-bold text-primary">Open full report →</Link></div></Popup></Marker>)}</MapContainer></div>
}
function MapPage(){
 const {reports}=useApp();const [query,setQuery]=useState("");const [cat,setCat]=useState("");const [stat,setStat]=useState("");const [place,setPlace]=useState("");const [from,setFrom]=useState("");const [to,setTo]=useState("");const [center,setCenter]=useState<[number,number]>([15.05,78.7]);const [gpsError,setGpsError]=useState("");
 const filtered=useMemo(()=>reports.filter(r=>(!cat||r.problemType===cat)&&(!stat||r.status===stat)&&(!place||r.locationName.toLowerCase().includes(place.toLowerCase()))&&(!query||`${r.id} ${r.description} ${r.locationName} ${r.problemType} ${r.farmerName}`.toLowerCase().includes(query.toLowerCase()))&&(!from||r.date>=from)&&(!to||r.date<=to)),[reports,cat,stat,place,query,from,to]);
 function locate(){if(!navigator.geolocation){setGpsError("Location is not available in this browser.");return}navigator.geolocation.getCurrentPosition(p=>{setCenter([p.coords.latitude,p.coords.longitude]);setGpsError("")},()=>setGpsError("Location permission was denied. Allow access to center the map near you."))}
 return <div className="mx-auto max-w-[1440px] px-4 py-8 sm:px-8"><div className="mb-6 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="eyebrow">COMMUNITY FIELD MAP</p><h1 className="serif mt-2 text-4xl sm:text-5xl">See the field picture.</h1><p className="mt-2 text-sm text-muted-foreground">Explore reported issues and support progress across the region.</p></div><Link href="/report" data-testid="link-map-report" className="inline-flex w-fit items-center gap-2 rounded-full bg-primary px-5 py-3 text-sm font-bold text-primary-foreground"><Plus size={16}/> Report an issue</Link></div>
  <div className="mb-4 flex flex-wrap items-center gap-2 rounded-2xl border border-border bg-card p-3"><div className="relative min-w-[220px] flex-1"><Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" size={16}/><input data-testid="input-map-search" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search reports or locations…" className="input !min-h-10 !pl-9"/></div><select data-testid="select-map-category" value={cat} onChange={e=>setCat(e.target.value)} className="input !min-h-10 !w-auto"><option value="">All issue types</option>{categories.map(c=><option key={c}>{c}</option>)}</select><select data-testid="select-map-status" value={stat} onChange={e=>setStat(e.target.value)} className="input !min-h-10 !w-auto"><option value="">All statuses</option>{statuses.map(s=><option key={s}>{s}</option>)}</select><input data-testid="input-map-location" value={place} onChange={e=>setPlace(e.target.value)} placeholder="Filter by location" className="input !min-h-10 !w-40"/><div className="flex items-center gap-1"><input aria-label="Filter from date" data-testid="input-map-date-from" type="date" value={from} onChange={e=>setFrom(e.target.value)} className="input !min-h-10 !w-[135px]"/><span className="text-xs text-muted-foreground">to</span><input aria-label="Filter through date" data-testid="input-map-date-to" type="date" value={to} onChange={e=>setTo(e.target.value)} className="input !min-h-10 !w-[135px]"/></div><Button kind="outline" className="!h-10 !min-w-[92px] !shrink-0 !whitespace-nowrap !px-3 !py-2" onClick={()=>{setQuery("");setCat("");setStat("");setPlace("");setFrom("");setTo("")}} data-testid="button-reset-map-filters"><Filter size={15}/> Reset</Button><Button kind="light" className="!h-10 !min-w-[108px] !shrink-0 !whitespace-nowrap !px-3 !py-2" onClick={locate} data-testid="button-map-gps"><LocateFixed size={15}/><span>Near me</span></Button></div>
 {gpsError&&<p className="mb-3 text-sm text-[#984d36]" data-testid="status-map-gps">{gpsError}</p>}<div className="mb-3 flex flex-wrap items-center justify-between gap-3"><p className="text-sm"><b data-testid="text-map-result-count">{filtered.length}</b> reports visible <span className="text-muted-foreground">· click a marker for details</span></p><div className="flex flex-wrap gap-3">{categories.map(c=><span key={c} className="flex items-center gap-1.5 text-[10px] text-muted-foreground"><i className="h-2.5 w-2.5 rounded-full" style={{background:categoryColor[c]}}/>{c}</span>)}</div></div>
  <MapView reports={filtered} height="min(68vh,720px)" center={center}/><div className="mt-7"><Panel title="Reports in view" sub="Sorted by most recent field update"><ReportRows rows={filtered} publicView/></Panel></div>
 </div>
}
function distanceKm(a:[number,number],b:[number,number]){const radians=(value:number)=>value*Math.PI/180;const dLat=radians(b[0]-a[0]),dLon=radians(b[1]-a[1]);const n=Math.sin(dLat/2)**2+Math.cos(radians(a[0]))*Math.cos(radians(b[0]))*Math.sin(dLon/2)**2;return 6371*2*Math.atan2(Math.sqrt(n),Math.sqrt(1-n))}
function Dashboard(){
 const {reports,user}=useApp();const [search,setSearch]=useState("");const [status,setStatus]=useState("");const [access,setAccess]=useState<Record<string,boolean>>(()=>getAccountAccess());const [gpsPoint,setGpsPoint]=useState<[number,number]|null>(null);const [gpsBusy,setGpsBusy]=useState(false);const [gpsError,setGpsError]=useState("");
 if(!user)return <Login redirect="/dashboard"/>;
 const own=user.role==="Farmer";const visible=own?reports.filter(r=>r.farmerEmail.toLowerCase()===user.email.toLowerCase()):reports;const filtered=visible.filter(r=>(!status||r.status===status)&&(`${r.id} ${r.locationName} ${r.problemType} ${r.farmerName}`.toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
 const active=reports.filter(r=>r.status!=="Resolved").length;const resolved=reports.filter(r=>r.status==="Resolved").length;const categoryData=categories.map(c=>({name:c.split(" ")[0],count:visible.filter(r=>r.problemType===c).length,color:categoryColor[c]}));const statusData=statuses.map(s=>({name:s,value:visible.filter(r=>r.status===s).length}));const radiusKm=25;const nearby=gpsPoint?reports.filter(r=>distanceKm(gpsPoint,[r.latitude,r.longitude])<=radiusKm):[];
 function requestGps(){if(!navigator.geolocation){setGpsError("Location services are unavailable in this browser. You can still review all reports.");return}setGpsBusy(true);setGpsError("");navigator.geolocation.getCurrentPosition(position=>{setGpsPoint([position.coords.latitude,position.coords.longitude]);setGpsBusy(false)},error=>{setGpsBusy(false);setGpsError(error.code===1?"Location permission was denied. Allow location access to calculate reports within 25 km, or continue with all reports.":"We couldn't get your location. Try again, or continue with all reports.")},{enableHighAccuracy:true,timeout:12000})}
 function toggleAccount(email:string,enabled:boolean){setAccountEnabled(email,enabled);setAccess(getAccountAccess())}
 return <div className="mx-auto max-w-[1440px] px-5 py-9 sm:px-8"><div className="mb-8 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="eyebrow">{user.role.toUpperCase()} WORKSPACE</p><h1 className="serif mt-2 text-4xl sm:text-5xl">{own?"Your field reports":user.role==="Admin"?"Community overview":"Field support desk"}.</h1><p className="mt-2 text-sm text-muted-foreground">{own?"Follow your reports and see updates from your local team.":user.role==="Admin"?"A live view of community concerns and field response.":"Review reports from across the region and keep the next step moving."}</p></div><div className="flex gap-2"><Link href="/map" className="inline-flex items-center gap-2 rounded-xl border border-border bg-card px-4 py-2.5 text-sm font-semibold"><MapIcon size={16}/> View map</Link>{own&&<Link href="/report" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground"><Plus size={16}/> New report</Link>}</div></div>
 {user.role==="Admin"?<div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{<><Stat label="Total farmers" value={accounts.filter(a=>a.role==="Farmer").length} caption="Registered demo farmer accounts" icon={Users}/><Stat label="Total officers" value={accounts.filter(a=>a.role==="Officer").length} caption="Agriculture field accounts" icon={ShieldCheck}/><Stat label="Total reports" value={reports.length} caption="Across the full community" icon={ClipboardList}/><Stat label="Resolved reports" value={resolved} caption="Closed with a recorded outcome" icon={CheckCircle2}/><Stat label="Active reports" value={active} caption="Reported or currently in progress" icon={Activity}/></>}</div>:user.role==="Officer"?<><div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Stat label="Total reports" value={reports.length} caption="Across the full community" icon={ClipboardList}/><Stat label="Active reports" value={active} caption="Reported or in progress" icon={Activity} tone="orange"/><Stat label="Resolved reports" value={resolved} caption="Support outcome recorded" icon={CheckCircle2}/><Stat label="Reports near you" value={gpsPoint?nearby.length:"—"} caption={gpsPoint?`Within ${radiusKm} km straight-line distance`:"Share your location to calculate proximity"} icon={MapPin}/></div><div className="mt-4 flex flex-wrap items-center gap-3 rounded-2xl border border-border bg-card p-4"><Button kind="light" onClick={requestGps} disabled={gpsBusy} data-testid="button-officer-nearby-gps"><LocateFixed size={16}/>{gpsBusy?"Getting location…":gpsPoint?"Refresh nearby count":"Find reports near me"}</Button><p className="text-xs text-muted-foreground" data-testid="text-officer-radius">Nearby = reports within {radiusKm} km by Haversine great-circle distance from your current GPS coordinates.</p>{gpsPoint&&<p className="w-full text-xs font-semibold text-primary" data-testid="text-officer-gps-coordinates">Using GPS {gpsPoint[0].toFixed(4)}, {gpsPoint[1].toFixed(4)} · {nearby.length} reports in range.</p>}{gpsError&&<p role="status" className="w-full text-xs text-[#984d36]" data-testid="status-officer-gps-error">{gpsError}</p>}</div></>:<div className="grid grid-cols-2 gap-3 lg:grid-cols-4"><Stat label="Your reports" value={visible.length} caption="Reports you have submitted" icon={ClipboardList}/><Stat label="Awaiting review" value={visible.filter(r=>r.status==="Reported").length} caption="New concerns to assess" icon={Bell} tone="orange"/><Stat label="In progress" value={visible.filter(r=>r.status==="In Progress").length} caption="Support underway" icon={Activity}/><Stat label="Resolved" value={visible.filter(r=>r.status==="Resolved").length} caption="Issues with a clear outcome" icon={CheckCircle2}/></div>}
 {user.role!=="Farmer"&&<div className="mt-5 grid gap-5 lg:grid-cols-[1.25fr_.75fr]"><Panel title="Issue categories" sub="Where the community needs support"><div className="h-[245px] p-4"><ResponsiveContainer width="100%" height="100%"><BarChart data={categoryData} margin={{top:10,right:8,left:-22,bottom:2}}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e7e8df"/><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{fontSize:11,fill:"#6b796e"}}/><YAxis allowDecimals={false} tickLine={false} axisLine={false} tick={{fontSize:11,fill:"#6b796e"}}/><ChartTooltip/><Bar dataKey="count" radius={[6,6,0,0]}>{categoryData.map((x,i)=><Cell key={i} fill={x.color}/>)}</Bar></BarChart></ResponsiveContainer></div></Panel><Panel title="Resolution progress" sub="Report status across the region"><div className="flex h-[245px] items-center justify-center"><div className="h-[220px] w-full"><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={statusData} dataKey="value" nameKey="name" innerRadius={56} outerRadius={82} paddingAngle={4}>{statusData.map((s,i)=><Cell key={s.name} fill={["#c8754e","#d3a252","#51845e"][i]}/>)}</Pie><ChartTooltip/></PieChart></ResponsiveContainer></div><div className="mr-5 space-y-3">{statusData.map((s,i)=><div key={s.name} className="flex items-center gap-2 text-xs"><span className="h-2.5 w-2.5 rounded-full" style={{background:["#c8754e","#d3a252","#51845e"][i]}}/><span className="text-muted-foreground">{s.name}</span><b>{s.value}</b></div>)}</div></div></Panel></div>}
 {user.role==="Admin"&&<div className="mt-5"><Panel title="User management" sub="Demo-account access is shared across browser sessions"><div className="overflow-x-auto"><table className="w-full min-w-[600px] text-left"><thead><tr className="border-b border-border text-[10px] uppercase tracking-widest text-muted-foreground"><th className="px-5 py-3">Name</th><th className="px-5 py-3">Email</th><th className="px-5 py-3">Role</th><th className="px-5 py-3">Access</th><th className="px-5 py-3">Action</th></tr></thead><tbody>{accounts.map(account=>{const enabled=access[account.email]!==false;const self=user.email===account.email&&user.role==="Admin";return <tr key={account.email} data-testid={`row-user-${account.role.toLowerCase()}`} className="border-b border-border/70 last:border-0"><td className="px-5 py-4 text-sm font-semibold">{account.name}</td><td className="px-5 py-4 text-sm text-muted-foreground">{account.email}</td><td className="px-5 py-4 text-xs font-bold">{account.role}</td><td className="px-5 py-4"><span data-testid={`status-account-${account.role.toLowerCase()}`} className={`rounded-full px-2.5 py-1 text-xs font-bold ${enabled?"bg-[#e2efdf] text-[#35633d]":"bg-[#f8e5dc] text-[#a95437]"}`}>{enabled?"Enabled":"Disabled"}</span></td><td className="px-5 py-4"><Button kind={enabled?"outline":"light"} disabled={self} onClick={()=>toggleAccount(account.email,!enabled)} data-testid={`button-account-toggle-${account.role.toLowerCase()}`}>{self?"Signed-in admin":enabled?"Disable access":"Enable access"}</Button></td></tr>})}</tbody></table></div><p className="px-5 pb-4 text-xs text-muted-foreground">Demo credentials remain visible on the sign-in screen; disabled accounts are rejected at login. Your current admin access cannot be disabled.</p></Panel></div>}
 <div className="mt-5"><Panel title={own?"Your reports":"Recent field reports"} sub={own?"Track each reported concern":"Search and manage incoming concerns"} action={<span className="rounded-full bg-[#e9eee1] px-3 py-1.5 text-xs font-bold">{filtered.length} shown</span>}><div className="flex flex-wrap gap-2 border-b border-border p-4"><div className="relative min-w-[220px] flex-1"><Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground"/><input data-testid="input-dashboard-search" value={search} onChange={e=>setSearch(e.target.value)} className="input !min-h-10 !pl-9" placeholder="Search reports, people, locations…"/></div><select data-testid="select-dashboard-status" value={status} onChange={e=>setStatus(e.target.value)} className="input !min-h-10 !w-auto"><option value="">All statuses</option>{statuses.map(s=><option key={s}>{s}</option>)}</select></div><ReportRows rows={filtered} officer={user.role==="Officer"} admin={user.role==="Admin"}/></Panel></div>
 </div>
}
function MyReports(){const {user}=useApp();return user?.role==="Farmer"?<Dashboard/>:<Login redirect="/my-reports"/>}
function Login({redirect="/dashboard"}:{redirect?:string}){
 const {setUser}=useApp();const [,setPath]=useLocation();const [email,setEmail]=useState("");const [password,setPassword]=useState("");const [error,setError]=useState("");const [loading,setLoading]=useState(false);
  function submit(e:React.FormEvent){e.preventDefault();setError("");setLoading(true);const account=accounts.find(a=>a.email.toLowerCase()===email.trim().toLowerCase()&&a.password===password);setTimeout(()=>{if(!account||!["Farmer","Officer","Admin"].includes(account.role)){setError("Those details don’t match a demo account. Check the email and password and try again.");setLoading(false);return}if(!getAccountAccess()[account.email]){setError("This demo account has been disabled by an administrator. Contact your network admin to restore access.");setLoading(false);return}const signed={email:account.email,role:account.role,name:account.name};localStorage.setItem("smartagri.session",JSON.stringify(signed));setUser(signed);setLoading(false);setPath(redirect)},300)}
 return <div className="mx-auto grid min-h-[calc(100dvh-160px)] max-w-[1160px] items-center gap-10 px-5 py-10 lg:grid-cols-[.95fr_1.05fr]"><div className="relative overflow-hidden rounded-[30px] bg-[#234a36] p-8 text-[#f3f2e8] sm:p-11"><div className="absolute -right-20 -top-20 h-64 w-64 rounded-full border border-white/10"/><p className="eyebrow !text-[#cadaaa]">SMARTAGRI FIELD NETWORK</p><h1 className="serif relative mt-6 max-w-[460px] text-4xl leading-tight sm:text-5xl">Support that starts where you grow.</h1><p className="relative mt-5 max-w-[420px] text-sm leading-6 text-[#d3dfd0]">Sign in to share a concern, follow your report, or coordinate support across your district.</p><div className="relative mt-10 space-y-4">{[{icon:MapPin,text:"Location-first reporting"},{icon:Activity,text:"Clear progress at every step"},{icon:Users,text:"Farmers and field teams together"}].map(x=><div key={x.text} className="flex items-center gap-3 text-sm text-[#e4eadb]"><span className="grid h-9 w-9 place-items-center rounded-xl bg-white/10"><x.icon size={17}/></span>{x.text}</div>)}</div></div><div className="mx-auto w-full max-w-[460px]"><p className="eyebrow">WELCOME BACK</p><h2 className="serif mt-2 text-4xl">Sign in to continue.</h2><p className="mt-2 text-sm text-muted-foreground">Use a demo role account to explore SmartAgri Map.</p><form onSubmit={submit} className="mt-7 space-y-4"><Field label="Email address"><input data-testid="input-login-email" type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="you@example.com" className="input"/></Field><Field label="Password"><input data-testid="input-login-password" type="password" value={password} onChange={e=>setPassword(e.target.value)} required placeholder="Enter your password" className="input"/></Field>{error&&<p role="alert" data-testid="status-login-error" className="rounded-xl bg-[#fae8e0] p-3 text-sm text-[#944d36]">{error}</p>}<Button type="submit" disabled={loading} className="w-full py-3" data-testid="button-login">{loading?"Signing in…":"Sign in"}<ArrowRight size={16}/></Button></form><div className="mt-7 rounded-2xl border border-border bg-[#f2f2e9] p-4"><h3 className="text-xs font-bold uppercase tracking-wider">Demo accounts</h3><div className="mt-3 space-y-2">{accounts.map(a=><button key={a.email} type="button" onClick={()=>{setEmail(a.email);setPassword(a.password)}} data-testid={`button-demo-${a.role.toLowerCase()}`} className="flex w-full items-center justify-between rounded-xl bg-card px-3 py-2.5 text-left transition-colors hover:bg-[#e8eee0]"><span><b className="block text-xs">{a.role}</b><small className="text-muted-foreground">{a.email}</small></span><span className="mono text-[10px] text-muted-foreground">{a.password}</span></button>)}</div></div><p className="mt-4 text-center text-[11px] text-muted-foreground">Client-only demo · Your session stays in this browser.</p></div></div>
}
function ReportDetail(){
 const {id}=useParams<{id:string}>();const {reports,user,setReports,toast}=useApp();const report=reports.find(r=>r.id===id);const [remark,setRemark]=useState(report?.remarks||"");useEffect(()=>{setRemark(report?.remarks||"")},[id]);if(!report)return <div className="mx-auto max-w-4xl px-5 py-24 text-center"><ClipboardList className="mx-auto text-[#9bab8a]" size={40}/><h1 className="serif mt-4 text-4xl">Report not found</h1><p className="mt-3 text-muted-foreground">It may have been removed or the link may be out of date.</p><Link href="/map" className="mt-5 inline-flex text-primary">Return to the report map</Link></div>;
 const currentReport=report;
 function saveRemark(){setReports(reports.map(r=>r.id===currentReport.id?{...r,remarks:remark}:r));toast("Your note has been saved.")}
 function advance(){if(!user||!["Officer","Admin"].includes(user.role))return;const next=currentReport.status==="Reported"?"In Progress":"Resolved";setReports(reports.map(r=>r.id===currentReport.id?{...r,status:next}:r));toast(`Report marked ${next}.`)}
 const canManage=user&&["Officer","Admin"].includes(user.role);
  return <div className="mx-auto max-w-[1150px] px-5 py-9 sm:px-8"><Link href="/map" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-primary">← Back to map</Link><div className="grid gap-5 lg:grid-cols-[1fr_390px]"><div className="space-y-5"><section className="rounded-3xl border border-border bg-card p-6 sm:p-8"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="eyebrow">{report.id} · FIELD REPORT</p><h1 className="serif mt-2 text-4xl">{report.problemType}</h1><p className="mt-2 flex items-center gap-1.5 text-sm text-muted-foreground"><MapPin size={15}/>{report.locationName}</p></div><Status status={report.status}/></div><div className="mt-7 grid grid-cols-2 gap-3 border-y border-border py-4 text-xs"><div><span className="text-muted-foreground">Reported by</span><b className="mt-1 block text-sm">{user&&(user.role==="Officer"||user.role==="Admin"||user.email.toLowerCase()===report.farmerEmail.toLowerCase())?report.farmerName:"Community farmer"}</b></div><div><span className="text-muted-foreground">Date noticed</span><b className="mt-1 block text-sm">{new Date(report.date+"T00:00:00").toLocaleDateString("en-IN",{day:"numeric",month:"long",year:"numeric"})}</b></div></div><h2 className="mt-6 text-sm font-bold">What’s happening</h2><p className="mt-2 whitespace-pre-wrap text-sm leading-7 text-[#57655b]">{report.description}</p>{report.image&&<img src={report.image} alt="Field issue" className="mt-6 max-h-[360px] w-full rounded-2xl object-cover"/>}</section><Panel title="Field team update" sub="Guidance and notes are shared with the farmer"><div className="p-5">{report.remarks?<div className="rounded-xl bg-[#edf1e5] p-4 text-sm leading-6" data-testid="text-report-remarks">{report.remarks}</div>:<p className="rounded-xl bg-[#f4f3ec] p-4 text-sm text-muted-foreground">No field team update yet. Updates will appear here.</p>}{canManage&&<><label className="mt-4 block text-xs font-bold">Add or update a note<textarea data-testid="input-detail-remark" value={remark} onChange={e=>setRemark(e.target.value)} rows={3} className="input mt-2 resize-y" placeholder="Share a next step or field visit update"/></label><Button kind="light" className="mt-3" onClick={saveRemark} data-testid="button-save-remark">Save note</Button></>}</div></Panel></div><aside className="space-y-5"><Panel title="Field location" sub={`${report.latitude.toFixed(5)}, ${report.longitude.toFixed(5)}`}><div className="p-3"><MapView reports={[report]} height="290px" center={[report.latitude,report.longitude]} zoom={13}/><a className="mt-3 flex items-center gap-1 text-xs font-semibold text-primary" href={`https://www.openstreetmap.org/?mlat=${report.latitude}&mlon=${report.longitude}#map=15/${report.latitude}/${report.longitude}`} target="_blank" rel="noreferrer">Open coordinates in OpenStreetMap <ArrowUpRight size={13}/></a></div></Panel><section className="rounded-2xl border border-border bg-card p-5"><p className="eyebrow">STATUS TIMELINE</p><div className="mt-5 space-y-4">{statuses.map((s,i)=>{const complete=statuses.indexOf(report.status)>=i;return <div className="flex gap-3" key={s}><div className={`grid h-7 w-7 shrink-0 place-items-center rounded-full ${complete?"bg-[#dfeada] text-primary":"bg-muted text-muted-foreground"}`}>{complete?<Check size={14}/>:<span className="text-[10px]">{i+1}</span>}</div><div className="pb-1"><b className={`text-sm ${complete?"":"text-muted-foreground"}`}>{s}</b><p className="mt-1 text-xs text-muted-foreground">{i===0?`Submitted ${new Date(report.createdAt).toLocaleDateString("en-IN")}`:i===1?"Field team is reviewing the issue":"Support outcome recorded"}</p></div></div>})}</div>{canManage&&report.status!=="Resolved"&&<Button onClick={advance} className="mt-5 w-full" data-testid="button-detail-advance">{report.status==="Reported"?"Mark in progress":"Mark resolved"}<ArrowRight size={15}/></Button>}</section></aside></div></div>
}
function LoginRoute(){const target=new URLSearchParams(window.location.search).get("return")||"/dashboard";const safeTarget=target.startsWith("/")&&!target.startsWith("//")?target:"/dashboard";return <Login redirect={safeTarget}/>}
function RoutedErrorBoundary({children}:{children:ReactNode}){const [location]=useLocation();return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>}
function AppRoot(){
 const [reportsState,setReportsState]=useState<Report[]>(()=>getReports());const [user,setUserState]=useState<User|null>(()=>{try{const v=JSON.parse(localStorage.getItem("smartagri.session")||"null");return v&&["Farmer","Officer","Admin"].includes(v.role)&&accounts.some(a=>a.email===v.email&&a.role===v.role)?v:null}catch{return null}});
 const setReports=(r:Report[])=>{setReportsState(r);saveReports(r)};const setUser=(u:User|null)=>setUserState(u);
 const [toastState,setToastState]=useState<{text:string;type:string}|null>(null);
 function toast(text:string,type:"success"|"error"="success"){setToastState({text,type});window.setTimeout(()=>setToastState(null),3200)}
 const value={reports:reportsState,setReports,user,setUser,toast};
  return <AppContext.Provider value={value}><Shell><RoutedErrorBoundary><Switch><Route path="/" component={Home}/><Route path="/map" component={MapPage}/><Route path="/report" component={ReportRoute}/><Route path="/dashboard" component={Dashboard}/><Route path="/about" component={About}/><Route path="/login" component={LoginRoute}/><Route path="/reports/:id" component={ReportDetail}/><Route path="/my-reports" component={MyReports}/><Route component={NotFound}/></Switch></RoutedErrorBoundary></Shell>{toastState&&<div role="status" data-testid="status-toast" className={`fixed bottom-5 right-5 z-[2000] flex max-w-[min(92vw,420px)] items-center gap-3 rounded-2xl px-5 py-4 text-sm font-semibold text-white shadow-xl ${toastState.type==="error"?"bg-[#984d36]":"bg-[#234a36]"}`}><CheckCircle2 size={18}/>{toastState.text}</div>}</AppContext.Provider>
}
function App(){return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/,"")}><AppRoot/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>}
export default App;
